import cn from 'classnames';
import Teaser from '../teaser/teaser';
import { ListItemProps, ListProps } from './list.types';
import { TeaserProps } from '../teaser/teaser.types';
import './list.scss';

const getDateFormat = (timestamp: number): string => {
  const date = new Date(timestamp);
  const day = String(date.getDate()).padStart(2, '0');
  const month = String(date.getMonth() + 1).padStart(2, '0');

  return `${date.getFullYear()}-${month}-${day}`;
};

function ListItemLinkContent({ showModificationDate, ...item }: ListItemProps & { showModificationDate?: boolean }) {
  return (
    <>
      <span className="cmp-list__item-title">{item.title}</span>
      {showModificationDate && item.lastModified ? (
        <span className="cmp-list__item-date">{getDateFormat(item.lastModified)}</span>
      ) : null}
      <span className="cmp-list__item-subtitle">{item.pretitle}</span>
    </>
  );
}

export function List({
  id,
  className,
  displayItemAsTeaser,
  showDescription,
  showModificationDate,
  linkItems,
  items,
  grid,
}: ListProps) {
  const listColCn = cn({
    'ds-brand-list-per-2': grid === 2,
    'ds-brand-list-per-3': grid === 3,
    'ds-brand-list-per-4': grid === 4,
    'ds-brand-list-per-5': grid === 5,
    'ds-brand-list-per-2-3': grid === 23,
    'ds-brand-list-per-3-2': grid === 32,
  });
  const classname = cn('list', listColCn, className);

  return (
    <div className={classname}>
      <ul id={id} data-cmp-data-layer="" className="cmp-list">
        {items.map((item) => (
          <li key={item.id} className="cmp-list__item" data-cmp-data-layer="">
            {displayItemAsTeaser ? (
              <Teaser {...(item as TeaserProps)} />
            ) : (
              <>
                {linkItems && item.link.valid ? (
                  <a className="cmp-list__item-link" data-cmp-clickable="" href={item.link.url} target={item.target}>
                    <ListItemLinkContent {...item} showModificationDate={showModificationDate} />
                  </a>
                ) : (
                  <ListItemLinkContent {...item} showModificationDate={showModificationDate} />
                )}
                {showDescription && item.description ? (
                  <span className="cmp-list__item-description">{item.description}</span>
                ) : null}
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default List;
